package vista;
import controlador.PrestamoController;import javax.swing.*;import javax.swing.table.DefaultTableModel;import java.awt.*;import java.util.List;
public class ReportesFrame extends JFrame {private final PrestamoController ctrl=new PrestamoController();private final JComboBox<String> tipo=new JComboBox<>(new String[]{"Libros más prestados","Historial de préstamos","Préstamos actualmente activos"});private final DefaultTableModel model=new DefaultTableModel(){public boolean isCellEditable(int r,int c){return false;}};private final JTable table=new JTable(model);public ReportesFrame(){super("Reportes bibliotecarios");setSize(900,500);setLocationRelativeTo(null);setLayout(new BorderLayout(8,8));JPanel top=new JPanel();top.add(new JLabel("Reporte:"));top.add(tipo);JButton ver=new JButton("Generar reporte");top.add(ver);add(top,BorderLayout.NORTH);add(new JScrollPane(table),BorderLayout.CENTER);ver.addActionListener(e->load());tipo.addActionListener(e->load());load();}
 private void load(){try{List<Object[]> rows;switch(tipo.getSelectedIndex()){case 0->{model.setColumnIdentifiers(new Object[]{"Libro","Cantidad de préstamos"});rows=ctrl.masPrestados();}case 1->{model.setColumnIdentifiers(new Object[]{"Estudiante","Libro","Fecha préstamo","Vencimiento","Devuelto"});rows=ctrl.historial();}default->{model.setColumnIdentifiers(new Object[]{"Estudiante","Libro","Fecha préstamo","Vencimiento","Estado"});rows=ctrl.pendientes();}}model.setRowCount(0);for(Object[] r:rows)model.addRow(r);}catch(Exception e){JOptionPane.showMessageDialog(this,"Error al generar reporte: "+e.getMessage());}}
}